class Solution {
    public Node construct(int[][] grid) {
        return build(grid, 0, 0, grid.length);
    }

    private Node build(int[][] grid, int row, int column, int size) {
        int value = grid[row][column];
        boolean uniform = true;
        for (int currentRow = row; currentRow < row + size; currentRow++) {
            for (int currentColumn = column; currentColumn < column + size; currentColumn++) {
                if (grid[currentRow][currentColumn] != value) {
                    uniform = false;
                    break;
                }
            }
            if (!uniform) {
                break;
            }
        }
        Node node = new Node();
        if (uniform) {
            node.val = value == 1;
            node.isLeaf = true;
            return node;
        }
        int half = size / 2;
        node.val = false;
        node.isLeaf = false;
        node.topLeft = build(grid, row, column, half);
        node.topRight = build(grid, row, column + half, half);
        node.bottomLeft = build(grid, row + half, column, half);
        node.bottomRight = build(grid, row + half, column + half, half);
        return node;
    }
}

