class Solution {
    private int[][] prefix;

    public Node construct(int[][] grid) {
        int size = grid.length;
        prefix = new int[size + 1][size + 1];
        for (int row = 0; row < size; row++) {
            for (int column = 0; column < size; column++) {
                prefix[row + 1][column + 1] = grid[row][column]
                    + prefix[row][column + 1]
                    + prefix[row + 1][column]
                    - prefix[row][column];
            }
        }
        return build(0, 0, size);
    }

    private Node build(int row, int column, int size) {
        int sum = prefix[row + size][column + size]
            - prefix[row][column + size]
            - prefix[row + size][column]
            + prefix[row][column];
        Node node = new Node();
        if (sum == 0 || sum == size * size) {
            node.val = sum != 0;
            node.isLeaf = true;
            return node;
        }
        int half = size / 2;
        node.val = false;
        node.isLeaf = false;
        node.topLeft = build(row, column, half);
        node.topRight = build(row, column + half, half);
        node.bottomLeft = build(row + half, column, half);
        node.bottomRight = build(row + half, column + half, half);
        return node;
    }
}
